@use '@angular/material' as mat;

// Compact density for inputs inside the dialog (52px height, labels intact).
$form-field-theme: mat.define-theme((
    density: (scale: -1),
));

.apd {
    --apd-surface: var(--app-widget-bg);
    --apd-surface-raised: var(--app-widget-header-bg);
    --apd-border: var(--app-widget-header-border);
    --apd-heading: var(--app-heading-color);
    --apd-body: var(--app-body-color);
    --apd-muted: var(--app-muted-color);
    --apd-eyebrow: var(--app-eyebrow-color);
    --apd-accent: var(--app-selection-color);
    --apd-accent-on: var(--app-selection-on-color);
    --apd-hover: var(--app-hover-overlay);
    --apd-segment-track: color-mix(in srgb, var(--app-shell-bg) 70%, transparent);
    --apd-segment-active: color-mix(in srgb, var(--app-widget-header-bg) 90%, white 5%);

    @include mat.form-field-density($form-field-theme);

    display: flex;
    flex-direction: column;
    background: var(--apd-surface);
    color: var(--apd-body);
    font-family: inherit;
    min-height: 0;
}

// ─── Header ──────────────────────────────────────────────────────────────────
.apd-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 20px 22px 18px;
}

.apd-title {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--apd-heading);
    line-height: 1.2;
}

.apd-close {
    appearance: none;
    border: 0;
    background: transparent;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--apd-muted);
    cursor: pointer;
    transition: background-color 120ms ease, color 120ms ease;

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
        line-height: 20px;
    }

    &:hover {
        background: var(--apd-hover);
        color: var(--apd-heading);
    }

    &:focus-visible {
        outline: 2px solid var(--apd-accent);
        outline-offset: 2px;
    }
}

.apd-divider {
    height: 1px;
    background: var(--apd-border);
    margin: 0;
}

// ─── Body ────────────────────────────────────────────────────────────────────
.apd-body {
    padding: 18px 22px 6px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    min-height: 0;
    overflow: auto;
}

// ─── Segmented control ──────────────────────────────────────────────────────
.apd-segmented {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    background: var(--apd-segment-track);
    border-radius: 12px;
    padding: 4px;
    gap: 2px;

    &--sub {
        background: color-mix(in srgb, var(--apd-segment-track) 70%, transparent);
    }
}

.apd-segment {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--apd-body);
    padding: 8px 14px;
    border-radius: 9px;
    font: inherit;
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    line-height: 1.3;
    transition:
        background-color 160ms ease,
        color 160ms ease,
        box-shadow 160ms ease;

    &:hover:not(.active) {
        color: var(--apd-heading);
    }

    &.active {
        background: var(--apd-segment-active);
        color: var(--apd-heading);
        box-shadow:
            0 1px 2px rgba(0, 0, 0, 0.18),
            0 0 0 1px var(--apd-border);
    }

    &:focus-visible {
        outline: 2px solid var(--apd-accent);
        outline-offset: 1px;
    }
}

// ─── Form area ───────────────────────────────────────────────────────────────
.apd-form-area {
    min-height: 0;
    padding-top: 4px;

    form {
        display: flex;
        flex-direction: column;
        gap: 4px;
    }

    .w-full {
        width: 100%;
    }

    // Material form-field refresh — subtle, dark, rounded outline.
    .mat-mdc-form-field {
        --mdc-outlined-text-field-outline-color: var(--apd-border);
        --mdc-outlined-text-field-hover-outline-color: var(--apd-muted);
        --mdc-outlined-text-field-focus-outline-color: var(--apd-accent);
        --mdc-outlined-text-field-container-shape: 10px;
        --mdc-outlined-text-field-label-text-color: var(--apd-muted);
        --mdc-outlined-text-field-input-text-color: var(--apd-heading);
        --mdc-outlined-text-field-caret-color: var(--apd-accent);
        width: 100%;
    }

    .mat-mdc-text-field-wrapper {
        background: color-mix(in srgb, var(--apd-surface-raised) 75%, transparent);
        border-radius: 10px;
    }

    .mat-mdc-form-field-subscript-wrapper {
        font-size: 11px;
        letter-spacing: 0.01em;

        .mat-mdc-form-field-hint-wrapper,
        .mat-mdc-form-field-error-wrapper {
            padding: 0 14px;
        }

        .mat-mdc-form-field-hint {
            color: var(--apd-muted);
        }
    }

    textarea.mat-mdc-input-element {
        min-height: 140px;
        padding-top: 6px;
    }
}

// ─── File upload override (stays on-theme) ──────────────────────────────────
.apd .file-upload {
    margin: 6px 0 12px;
    border: 1px dashed var(--apd-border);
    border-radius: 14px;
    background: color-mix(in srgb, var(--apd-surface-raised) 35%, transparent);
    padding: 28px 20px;
    transition: border-color 160ms ease, background-color 160ms ease;

    &:hover {
        border-color: var(--apd-accent);
        background: color-mix(in srgb, var(--apd-accent) 6%, transparent);
    }

    .upload-icon {
        color: var(--apd-muted);
        font-size: 44px;
        width: 44px;
        height: 44px;
    }

    .label {
        color: var(--apd-body);
        font-size: 13px;
        line-height: 1.45;
    }
}

// Text-area form field gets more room to breathe
.apd app-text-import .mat-mdc-form-field {
    min-height: 180px;
}

// ─── Footer / actions ────────────────────────────────────────────────────────
.apd-footer {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 8px;
    padding: 16px 22px 20px;
    border-top: 1px solid var(--apd-border);
    margin-top: 6px;
}

.apd-btn {
    appearance: none;
    border: 0;
    font: inherit;
    font-size: 13.5px;
    font-weight: 600;
    letter-spacing: 0.005em;
    padding: 10px 18px;
    border-radius: 10px;
    cursor: pointer;
    transition:
        background-color 160ms ease,
        color 160ms ease,
        box-shadow 160ms ease,
        transform 160ms ease,
        opacity 160ms ease;

    &:disabled {
        opacity: 0.45;
        cursor: not-allowed;
    }

    &:focus-visible {
        outline: 2px solid var(--apd-accent);
        outline-offset: 2px;
    }

    &--ghost {
        background: transparent;
        color: var(--apd-body);
        box-shadow: inset 0 0 0 1px var(--apd-border);

        &:hover:not(:disabled) {
            background: var(--apd-hover);
            color: var(--apd-heading);
        }
    }

    &--primary {
        background: var(--apd-accent);
        color: var(--apd-accent-on);
        box-shadow:
            0 1px 2px rgba(0, 0, 0, 0.18),
            0 6px 16px color-mix(in srgb, var(--apd-accent) 30%, transparent);

        &:hover:not(:disabled) {
            background: color-mix(in srgb, var(--apd-accent) 88%, white 10%);
            transform: translateY(-1px);
        }

        &:active:not(:disabled) {
            transform: translateY(0);
        }
    }
}

// ─── Light theme tweaks ──────────────────────────────────────────────────────
// In light mode the raised surface is pure white — nudge the segmented track
// to be a softer tinted grey so active segments pop against the container.
html:not(.dark-theme) .apd {
    --apd-segment-track: color-mix(in srgb, var(--app-content-bg) 70%, transparent);
    --apd-segment-active: #ffffff;

    .apd-segment.active {
        box-shadow:
            0 1px 2px rgba(0, 0, 0, 0.06),
            0 0 0 1px rgba(0, 0, 0, 0.06);
    }

    .mat-mdc-text-field-wrapper {
        background: #ffffff;
    }

    .apd-btn--primary {
        color: #ffffff;
    }
}

