@use '@angular/material' as mat;
@use '../../../libs/ui/components/src/lib/resizable/resizable.scss';

// ─── Refined input density preset ────────────────────────────────────────────
// Scale -2 → 48px outlined fields. Shared between the add-playlist dialog and
// the settings page so all app forms look identical.
$app-refined-input-density: mat.define-theme((
    density: (scale: -2),
));

// ─── Tailwind CSS ─────────────────────────────────────────────────────────────
// Preflight is disabled in tailwind.config.js to avoid conflicts with
// Angular Material. Only components + utilities are loaded.
@tailwind base;
@tailwind components;
@tailwind utilities;

// ─── Third-party ─────────────────────────────────────────────────────────────
@import '@yangkghjh/videojs-aspect-ratio-panel/dist/videojs-aspect-ratio-panel.css';
@import 'material-design-icons-iconfont/dist/material-design-icons.css';

// ─── Bundled Fonts ────────────────────────────────────────────────────────────
@import '@fontsource/dm-sans/400.css';
@import '@fontsource/dm-sans/500.css';
@import '@fontsource/dm-sans/600.css';
@import '@fontsource/roboto/300.css';
@import '@fontsource/roboto/400.css';
@import '@fontsource/roboto/500.css';
@import '@fontsource/jetbrains-mono/400.css';
@import '@fontsource/jetbrains-mono/500.css';
@import '@fontsource/crimson-pro/400.css';
@import '@fontsource/crimson-pro/600.css';
@import '@fontsource/crimson-pro/700.css';

// ─── Shared Components ────────────────────────────────────────────────────────

app-root.macos-platform .current-playlist {
    padding-top: 30px;
}

app-root.macos-platform app-navigation .portal-status-container {
    padding-top: 30px;
}

// ─── Base ─────────────────────────────────────────────────────────────────────
body,
html {
    user-select: none;
    margin: 0;
    padding: 0;
    height: 100%;
    font-family:
        'DM Sans',
        'Roboto',
        -apple-system,
        BlinkMacSystemFont,
        'Segoe UI',
        'Helvetica Neue',
        Arial,
        sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

// Re-enable context menu and text selection for input fields
input,
textarea {
    user-select: text;
}

@media (display-mode: standalone) {
    body {
        overscroll-behavior-y: contain;
        overflow: hidden;
    }
}

// ─── Utilities ────────────────────────────────────────────────────────────────
.mat-tab-label-active {
    opacity: 1 !important;
}

input,
button,
textarea,
:focus {
    outline: none;
}

// ─── Dark Theme ───────────────────────────────────────────────────────────────
.dark-theme {
    background: var(--mat-sys-surface) !important;

    // Refined scrollbar for dark mode
    ::-webkit-scrollbar {
        width: 6px;
        height: 6px;
    }

    ::-webkit-scrollbar-track {
        background: transparent;
    }

    ::-webkit-scrollbar-thumb {
        background-color: var(--mat-sys-outline-variant);
        border-radius: 999px;

        &:hover {
            background-color: var(--mat-sys-outline);
        }
    }
}

.scroll-viewport-portals {
    min-height: calc(100vh - 170px) !important;
    overflow-x: hidden !important;
}

.mat-drawer-inner-container {
    overflow: hidden !important;
}

.cdk-overlay-backdrop {
    backdrop-filter: blur(4px);
}

// Full-screen overlay dialogs (global search/recent) must stay interactive in Electron.
.global-search-overlay,
.global-search-overlay .mat-mdc-dialog-surface,
.global-search-overlay .mat-mdc-dialog-container {
    app-region: no-drag;
}

.mat-mdc-snack-bar-container.settings-snackbar {
    margin-bottom: calc(76px + env(safe-area-inset-bottom, 0px));
}

// ─── Add-playlist dialog panel ────────────────────────────────────────────────
// Custom rounded surface + subtle hairline border, reused across themes.
.add-playlist-dialog-panel {
    .mat-mdc-dialog-surface {
        border-radius: 18px !important;
        background: var(--app-widget-bg) !important;
        padding: 0 !important;
        overflow: hidden;
        box-shadow:
            0 24px 60px rgba(0, 0, 0, 0.35),
            0 2px 8px rgba(0, 0, 0, 0.18),
            0 0 0 1px var(--app-widget-header-border);
    }

    .mat-mdc-dialog-container .mdc-dialog__container {
        padding: 0;
    }
}

