@import '@fontsource/crimson-pro/600.css';
@import '@fontsource/crimson-pro/700.css';

// ─── Shared Components ────────────────────────────────────────────────────────

app-root.macos-platform .current-playlist {
    padding-top: 30px;
}

app-root.macos-platform app-navigation .portal-status-container {
    padding-top: 30px;
}

// ─── Base ─────────────────────────────────────────────────────────────────────
body,
html {
    user-select: none;
    margin: 0;
    padding: 0;
    height: 100%;
    font-family:
        'DM Sans',
        'Roboto',
        -apple-system,
        BlinkMacSystemFont,
        'Segoe UI',
        'Helvetica Neue',
        Arial,
        sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

// Re-enable context menu and text selection for input fields
input,
textarea {
    user-select: text;
}

@media (display-mode: standalone) {
    body {
        overscroll-behavior-y: contain;
        overflow: hidden;
    }
}

// ─── Utilities ────────────────────────────────────────────────────────────────
.mat-tab-label-active {
    opacity: 1 !important;
}

input,
button,
textarea,
:focus {
    outline: none;
}

// ─── Dark Theme ───────────────────────────────────────────────────────────────
.dark-theme {
    background: var(--mat-sys-surface) !important;

    // Refined scrollbar for dark mode
    ::-webkit-scrollbar {
        width: 6px;
        height: 6px;
    }

    ::-webkit-scrollbar-track {
        background: transparent;
    }

    ::-webkit-scrollbar-thumb {
        background-color: var(--mat-sys-outline-variant);
        border-radius: 999px;

        &:hover {
            background-color: var(--mat-sys-outline);
        }
    }
}

.scroll-viewport-portals {
    min-height: calc(100vh - 170px) !important;
    overflow-x: hidden !important;
}

.mat-drawer-inner-container {
    overflow: hidden !important;
}

.cdk-overlay-backdrop {
    backdrop-filter: blur(4px);
}

// Full-screen overlay dialogs (global search/recent) must stay interactive in Electron.
.global-search-overlay,
.global-search-overlay .mat-mdc-dialog-surface,
.global-search-overlay .mat-mdc-dialog-container {
    app-region: no-drag;
}

.mat-mdc-snack-bar-container.settings-snackbar {
    margin-bottom: calc(76px + env(safe-area-inset-bottom, 0px));
}

// ─── Global refined outlined inputs ──────────────────────────────────────────
// Applied app-wide: every mat-form-field uses the compact 48px outlined look
// by default. The default `appearance` is set to `outline` via
// MAT_FORM_FIELD_DEFAULT_OPTIONS in app.config.ts, so this styling matches.
@include mat.form-field-density($app-refined-input-density);

html {
    --app-input-bg: color-mix(in srgb, var(--app-widget-bg) 85%, white 7%);
}

.mat-mdc-form-field {
    --mdc-outlined-text-field-outline-color: var(--app-widget-header-border);
    --mdc-outlined-text-field-hover-outline-color: var(--app-muted-color);
    --mdc-outlined-text-field-focus-outline-color: var(--app-selection-color);
    --mdc-outlined-text-field-container-shape: 10px;
    --mdc-outlined-text-field-label-text-color: var(--app-muted-color);
    --mdc-outlined-text-field-input-text-color: var(--app-heading-color);
    --mdc-outlined-text-field-caret-color: var(--app-selection-color);
    --mdc-outlined-text-field-label-text-size: 13px;
    --mdc-outlined-text-field-input-text-size: 13.5px;
}

// Dark fill + rounded wrapper, scoped to outlined appearance so filled
// form-fields elsewhere keep their built-in Material background behavior.
.mat-form-field-appearance-outline .mat-mdc-text-field-wrapper {
    background: var(--app-input-bg);
    border-radius: 10px;
}

.mat-mdc-form-field-subscript-wrapper {
    font-size: 11px;
    letter-spacing: 0.01em;
    margin-top: 2px;

    .mat-mdc-form-field-hint-wrapper,
    .mat-mdc-form-field-error-wrapper {
        padding: 0 12px;
    }

    .mat-mdc-form-field-hint {
        color: var(--app-muted-color);
    }
}

// ─── Add-playlist dialog panel ────────────────────────────────────────────────
// Custom rounded surface + subtle hairline border, reused across themes.
.add-playlist-dialog-panel {
    .mat-mdc-dialog-surface {
        border-radius: 18px !important;
        background: var(--app-widget-bg) !important;
        padding: 0 !important;
        overflow: hidden;
        box-shadow:
            0 24px 60px rgba(0, 0, 0, 0.35),
            0 2px 8px rgba(0, 0, 0, 0.18),
            0 0 0 1px var(--app-widget-header-border);
    }

    .mat-mdc-dialog-container .mdc-dialog__container {
        padding: 0;
    }
}

