agent-browser --cdp 9222 click @e3 && sleep 2 && agent-browser --cdp 9222 eval '(() => {
  const fld = document.querySelector(".apd mat-form-field");
  if (!fld) return "no dialog field";
  const wrapper = fld.querySelector(".mat-mdc-text-field-wrapper");
  const infix = fld.querySelector(".mat-mdc-form-field-infix");
  const input = fld.querySelector("input, textarea");
  return JSON.stringify({
    wrapperBg: getComputedStyle(wrapper).backgroundColor,
    wrapperRadius: getComputedStyle(wrapper).borderRadius,
    infixH: infix?.offsetHeight,
    inputTextSize: input ? getComputedStyle(input).fontSize : null
  });
})()'

agent-browser --cdp 9222 eval '(() => {
  const wrapper = document.querySelector(".apd mat-form-field .mat-mdc-text-field-wrapper");
  if (!wrapper) return "no wrapper";
  // Walk up the CSS rules to find what sets background
  const matches = [];
  for (const sheet of document.styleSheets) {
    try {
      for (const rule of sheet.cssRules || []) {
        try {
          if (rule.style && rule.style.backgroundColor && wrapper.matches(rule.selectorText)) {
            matches.push({sel: rule.selectorText, bg: rule.style.backgroundColor});
          }
        } catch(e) {}
      }
    } catch(e) {}
  }
  return JSON.stringify(matches.slice(-5));
})()'

agent-browser --cdp 9222 eval '(() => {
  const wrapper = document.querySelector(".apd mat-form-field .mat-mdc-text-field-wrapper");
  if (!wrapper) return "no wrapper";
  const matches = [];
  for (const sheet of document.styleSheets) {
    try {
      const rules = sheet.cssRules || [];
      for (const rule of rules) {
        try {
          if (rule.style && rule.selectorText && wrapper.matches(rule.selectorText)) {
            const bg = rule.style.getPropertyValue("background") || rule.style.getPropertyValue("background-color");
            if (bg) matches.push({sel: rule.selectorText, bg: bg.substring(0, 80)});
          }
        } catch(e) {}
      }
    } catch(e) {}
  }
  return JSON.stringify(matches);
})()'

agent-browser --cdp 9222 eval '(() => {
  const wrapper = document.querySelector(".apd mat-form-field .mat-mdc-text-field-wrapper");
  if (!wrapper) return "no wrapper";
  let ancestors = [];
  let el = wrapper;
  while (el) {
    ancestors.push(el.tagName + (el.id ? "#"+el.id : "") + (el.className ? "."+String(el.className).split(" ").slice(0,2).join(".") : ""));
    el = el.parentElement;
  }
  const s = getComputedStyle(wrapper);
  return JSON.stringify({
    ancestors: ancestors.slice(0, 10),
    widgetBgAtWrapper: s.getPropertyValue("--app-widget-bg"),
    inputBgAtWrapper: s.getPropertyValue("--app-input-bg"),
  });
})()'

