49	export class PlaylistInfoComponent {
50	    private clipboard = inject(Clipboard);
51	    private datePipe = inject(DatePipe);
52	    private formBuilder = inject(UntypedFormBuilder);
53	    private playlistsService = inject(PlaylistsService);
54	    private store = inject(Store);
55	    private databaseService = inject(DatabaseService);
56	    private snackBar = inject(MatSnackBar);
57	    private translate = inject(TranslateService);
58	    public playlistData = inject<Playlist & { id: string }>(MAT_DIALOG_DATA);
59	
60	    readonly isDesktop = !!window.electron;
61	
62	    /** Playlist object */
63	    playlist: Playlist & { id: string };
64	
65	    /** Form group with playlist details */
66	    playlistDetails!: UntypedFormGroup;
67	
68	    constructor() {
69	        this.playlist = this.playlistData;
70	        this.createForm();
71	    }
72	
73	    /**
74	     * Create the form and set initial data on component init
75	     */
76	    createForm(): void {
77	        this.playlistDetails = this.formBuilder.group({
78	            _id: this.playlist._id,
79	            title: new FormControl(this.playlist.title, Validators.required),
80	            userAgent: this.playlist.userAgent || '',
81	            filename: new FormControl({
82	                value: this.playlist.filename || '',
83	                disabled: true,
84	            }),
