86	                value: this.playlist.count,
87	                disabled: true,
88	            }),
89	            importDate: new FormControl({
90	                value: this.datePipe.transform(this.playlist.importDate),
91	                disabled: true,
92	            }),
93	            url: new FormControl({
94	                value: this.playlist.url,
95	                disabled: true,
96	            }),
97	            filePath: new FormControl({
98	                value: this.playlist.filePath,
99	                disabled: true,
100	            }),
101	            autoRefresh: new FormControl(this.playlist.autoRefresh),
102	            serverUrl: new FormControl(this.playlist.serverUrl),
103	            username: new FormControl(this.playlist.username),
104	            password: new FormControl(this.playlist.password),
105	            macAddress: new FormControl(this.playlist.macAddress),
106	            portalUrl: new FormControl(this.playlist.portalUrl),
107	            stalkerSerialNumber: new FormControl(
108	                this.playlist.stalkerSerialNumber
109	            ),
