.apd-btn {
    appearance: none;
    border: 0;
    font: inherit;
    font-size: 13.5px;
    font-weight: 600;
    letter-spacing: 0.005em;
    padding: 10px 18px;
    border-radius: 10px;
    cursor: pointer;
    transition:
        background-color 160ms ease,
        color 160ms ease,
        box-shadow 160ms ease,
        transform 160ms ease,
        opacity 160ms ease;

    &:disabled {
        opacity: 0.45;
        cursor: not-allowed;
    }

    &:focus-visible {
        outline: 2px solid var(--apd-accent);
        outline-offset: 2px;
    }

